                exceptions); // exceptions);

    generateBody(mv, 0);

    if (PCNOuter != null) {
        InstantiatingClassloader.optionalStaticsAndClassInitForTO(isf_list, cv);
        cv.dumpClass(PCNOuter, xldata);
    }
}

